create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, phone text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.addresses (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, phone text not null, address text not null, city text not null, state text not null, postal_code text not null, country text not null default 'India', is_default boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.orders (id uuid primary key default gen_random_uuid(), order_number text unique not null, user_id uuid not null references auth.users(id), status text not null default 'PENDING' check (status in ('PENDING','CONFIRMED','PROCESSING','PACKED','SHIPPED','DELIVERED','CANCELLED','RETURN_REQUESTED','RETURNED','REFUND_PENDING','REFUNDED')), payment_status text not null default 'UNPAID', subtotal_paise integer not null default 0, discount_paise integer not null default 0, shipping_paise integer not null default 0, tax_paise integer not null default 0, total_paise integer not null default 0, shipping_address jsonb not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.order_items (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, product_id uuid not null references public.products(id), product_name text not null, size text not null, quantity integer not null check (quantity > 0), unit_price_paise integer not null check (unit_price_paise >= 0));
create table if not exists public.admin_users (user_id uuid primary key references auth.users(id) on delete cascade, role text not null check (role in ('SUPER_ADMIN','ADMIN','ORDER_MANAGER','CONTENT_MANAGER')), created_at timestamptz not null default now());
alter table public.profiles enable row level security; alter table public.addresses enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security; alter table public.admin_users enable row level security;
drop policy if exists "Users manage own profile" on public.profiles; create policy "Users manage own profile" on public.profiles for all using (auth.uid() = id) with check (auth.uid() = id);
drop policy if exists "Users manage own addresses" on public.addresses; create policy "Users manage own addresses" on public.addresses for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
drop policy if exists "Users read own orders" on public.orders; create policy "Users read own orders" on public.orders for select using (auth.uid() = user_id);
drop policy if exists "Users read own order items" on public.order_items; create policy "Users read own order items" on public.order_items for select using (exists (select 1 from public.orders where orders.id = order_items.order_id and orders.user_id = auth.uid()));
drop policy if exists "Users read own admin role" on public.admin_users; create policy "Users read own admin role" on public.admin_users for select using (auth.uid() = user_id);
